package com.ironkinclan.api;

import com.ironkinclan.config.IronkinClanConfig;
import okhttp3.Request;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class IronkinClanApiClientTest
{
	private IronkinClanConfig config;
	private IronkinClanApiClient apiClient;

	@Before
	public void setUp()
	{
		config = mock(IronkinClanConfig.class);
		when(config.serverUrl()).thenReturn("https://ironkin.example.com");
		when(config.apiKey()).thenReturn("secret-key");

		apiClient = new IronkinClanApiClient(config);
	}

	@Test
	public void newItemListRequest_buildsExpectedUrlAndAuthHeader()
	{
		Request request = apiClient.newItemListRequest().build();

		assertEquals("https://ironkin.example.com/events/item-list", request.url().toString());
		assertEquals("secret-key", request.header(IronkinClanApiClient.API_KEY_HEADER));
	}

	@Test
	public void newSubmissionRequest_includesEventIdInPath()
	{
		Request request = apiClient.newSubmissionRequest("bounty-123").build();

		assertEquals("https://ironkin.example.com/events/bounty-123/submissions", request.url().toString());
		assertEquals("secret-key", request.header(IronkinClanApiClient.API_KEY_HEADER));
	}

	@Test
	public void baseUrl_stripsTrailingSlashFromServerUrl()
	{
		when(config.serverUrl()).thenReturn("https://ironkin.example.com/");

		Request request = apiClient.newItemListRequest().build();

		assertEquals("https://ironkin.example.com/events/item-list", request.url().toString());
	}
}

package com.ironkinclan.manager;

import com.google.gson.Gson;
import com.ironkinclan.api.IronkinClanApiClient;
import com.ironkinclan.config.IronkinClanConfig;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import net.runelite.client.ui.DrawManager;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Protocol;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import okio.Buffer;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentCaptor;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyLong;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class DropSubmissionManagerTest
{
	private OkHttpClient httpClient;
	private Call call;
	private ScheduledExecutorService executor;
	private DiagnosticListener listener;
	private DropSubmissionManager manager;

	@Before
	public void setUp()
	{
		IronkinClanConfig config = mock(IronkinClanConfig.class);
		when(config.serverUrl()).thenReturn("https://ironkin.example.com");
		when(config.apiKey()).thenReturn("secret-key");

		IronkinClanApiClient apiClient = new IronkinClanApiClient(config);
		httpClient = mock(OkHttpClient.class);
		call = mock(Call.class);
		when(httpClient.newCall(any(Request.class))).thenReturn(call);

		DrawManager drawManager = mock(DrawManager.class);
		executor = mock(ScheduledExecutorService.class);
		// Run scheduled retries synchronously and immediately so tests don't need to deal with
		// real delays - the backoff duration itself isn't the concern of these tests.
		doAnswer(invocation ->
		{
			Runnable retry = invocation.getArgument(0);
			retry.run();
			return null;
		}).when(executor).schedule(any(Runnable.class), anyLong(), any(TimeUnit.class));

		manager = new DropSubmissionManager(apiClient, httpClient, new Gson(), drawManager, executor);

		listener = mock(DiagnosticListener.class);
		manager.setListener(listener);
	}

	private void respondWith(int code)
	{
		doAnswer(invocation ->
		{
			Callback callback = invocation.getArgument(0);
			Response response = new Response.Builder()
				.request(new Request.Builder().url("https://ironkin.example.com/events/bounty-123/submissions").build())
				.protocol(Protocol.HTTP_1_1)
				.code(code)
				.message(code == 200 ? "OK" : "Error")
				.body(ResponseBody.create(MediaType.get("text/plain"), ""))
				.build();
			callback.onResponse(call, response);
			return null;
		}).when(call).enqueue(any(Callback.class));
	}

	private void respondWithFailure(IOException exception)
	{
		doAnswer(invocation ->
		{
			Callback callback = invocation.getArgument(0);
			callback.onFailure(call, exception);
			return null;
		}).when(call).enqueue(any(Callback.class));
	}

	private static BufferedImage testImage()
	{
		return new BufferedImage(4, 4, BufferedImage.TYPE_INT_ARGB);
	}

	@Test
	public void uploadDrop_success_postsToEventSubmissionUrlAndNotifiesListenerTrue()
	{
		respondWith(200);

		manager.uploadDrop("bounty-123", "PlayerName", 20997, "Twisted bow", 1720280000000L, Collections.emptyList(), testImage());

		ArgumentCaptor<Request> requestCaptor = ArgumentCaptor.forClass(Request.class);
		verify(httpClient).newCall(requestCaptor.capture());
		Request request = requestCaptor.getValue();

		assertEquals("https://ironkin.example.com/events/bounty-123/submissions", request.url().toString());
		assertEquals("secret-key", request.header(IronkinClanApiClient.API_KEY_HEADER));

		verify(listener).onDiagnosticEvent(eq("Captured screenshot for Twisted bow drop"), eq(true));
		verify(listener).onDiagnosticEvent(eq("Sent Twisted bow drop for PlayerName to bounty-123"), eq(true));
	}

	@Test
	public void uploadDrop_requestBody_containsDropFields() throws IOException
	{
		respondWith(200);

		manager.uploadDrop("bounty-123", "PlayerName", 20997, "Twisted bow", 1720280000000L, Collections.emptyList(), testImage());

		ArgumentCaptor<Request> requestCaptor = ArgumentCaptor.forClass(Request.class);
		verify(httpClient).newCall(requestCaptor.capture());
		Request request = requestCaptor.getValue();

		Buffer buffer = new Buffer();
		request.body().writeTo(buffer);
		String json = buffer.readUtf8();

		assertTrue(json.contains("\"username\":\"PlayerName\""));
		assertTrue(json.contains("\"itemid\":20997"));
		assertTrue(json.contains("\"timestamp\":1720280000000"));
		assertTrue(json.contains("\"imageData\":\""));
	}

	@Test
	public void uploadDrop_withParticipants_requestBody_containsParticipants() throws IOException
	{
		respondWith(200);

		manager.uploadDrop("bounty-123", "PlayerName", 20997, "Twisted bow", 1720280000000L,
			Arrays.asList("Clanmate1", "Clanmate2"), testImage());

		ArgumentCaptor<Request> requestCaptor = ArgumentCaptor.forClass(Request.class);
		verify(httpClient).newCall(requestCaptor.capture());
		Request request = requestCaptor.getValue();

		Buffer buffer = new Buffer();
		request.body().writeTo(buffer);
		String json = buffer.readUtf8();

		assertTrue(json.contains("\"participants\":[\"Clanmate1\",\"Clanmate2\"]"));
	}

	@Test
	public void uploadDrop_httpError_notifiesListenerFalse()
	{
		respondWith(500);

		manager.uploadDrop("bounty-123", "PlayerName", 20997, "Twisted bow", 1720280000000L, Collections.emptyList(), testImage());

		verify(listener).onDiagnosticEvent(any(String.class), eq(false));
	}

	@Test
	public void uploadDrop_networkFailure_retriesTwiceThenNotifiesListenerFalse()
	{
		respondWithFailure(new IOException("connection refused"));

		manager.uploadDrop("bounty-123", "PlayerName", 20997, "Twisted bow", 1720280000000L, Collections.emptyList(), testImage());

		// Initial attempt + 2 retries.
		verify(httpClient, times(3)).newCall(any(Request.class));
		verify(listener).onDiagnosticEvent(any(String.class), eq(false));
	}

	@Test
	public void uploadDrop_networkFailure_retriesWithIncreasingBackoff()
	{
		respondWithFailure(new IOException("connection refused"));

		manager.uploadDrop("bounty-123", "PlayerName", 20997, "Twisted bow", 1720280000000L, Collections.emptyList(), testImage());

		ArgumentCaptor<Long> delayCaptor = ArgumentCaptor.forClass(Long.class);
		verify(executor, times(2)).schedule(any(Runnable.class), delayCaptor.capture(), eq(TimeUnit.MILLISECONDS));
		assertEquals(2000L, (long) delayCaptor.getAllValues().get(0));
		assertEquals(4000L, (long) delayCaptor.getAllValues().get(1));
	}

	@Test
	public void uploadDrop_networkFailureThenSuccessOnRetry_notifiesListenerTrue()
	{
		// Fail on the first attempt, then succeed on the retry.
		doAnswer(invocation ->
		{
			Callback callback = invocation.getArgument(0);
			callback.onFailure(call, new IOException("connection refused"));
			return null;
		}).doAnswer(invocation ->
		{
			Callback callback = invocation.getArgument(0);
			Response response = new Response.Builder()
				.request(new Request.Builder().url("https://ironkin.example.com/events/bounty-123/submissions").build())
				.protocol(Protocol.HTTP_1_1)
				.code(200)
				.message("OK")
				.body(ResponseBody.create(MediaType.get("text/plain"), ""))
				.build();
			callback.onResponse(call, response);
			return null;
		}).when(call).enqueue(any(Callback.class));

		manager.uploadDrop("bounty-123", "PlayerName", 20997, "Twisted bow", 1720280000000L, Collections.emptyList(), testImage());

		verify(httpClient, times(2)).newCall(any(Request.class));
		verify(listener).onDiagnosticEvent(eq("Sent Twisted bow drop for PlayerName to bounty-123"), eq(true));
	}

	@Test
	public void uploadDrop_differentEventIds_postToDifferentUrls()
	{
		respondWith(200);

		manager.uploadDrop("bounty-123", "PlayerName", 20997, "Twisted bow", 1720280000000L, Collections.emptyList(), testImage());
		manager.uploadDrop("botw-123", "PlayerName", 20997, "Twisted bow", 1720280000000L, Collections.emptyList(), testImage());

		ArgumentCaptor<Request> requestCaptor = ArgumentCaptor.forClass(Request.class);
		verify(httpClient, times(2)).newCall(requestCaptor.capture());

		List<Request> requests = requestCaptor.getAllValues();
		assertTrue(requests.get(0).url().toString().endsWith("/events/bounty-123/submissions"));
		assertTrue(requests.get(1).url().toString().endsWith("/events/botw-123/submissions"));
	}
}

package com.ironkinclan.manager;

import com.google.gson.Gson;
import com.ironkinclan.api.IronkinClanApiClient;
import com.ironkinclan.config.IronkinClanConfig;
import com.ironkinclan.model.TrackedEventGroup;
import java.io.IOException;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import net.runelite.api.ItemComposition;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Protocol;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentCaptor;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyLong;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class TrackedItemManagerTest
{
	private IronkinClanConfig config;
	private OkHttpClient httpClient;
	private ItemManager itemManager;
	private ClientThread clientThread;
	private ScheduledExecutorService executor;
	private Call call;
	private TrackedItemManager manager;

	private DiagnosticListener diagnosticListener;
	private TrackedItemManager.Listener listener;

	@Before
	public void setUp()
	{
		config = mock(IronkinClanConfig.class);
		when(config.serverUrl()).thenReturn("https://ironkin.example.com");
		when(config.apiKey()).thenReturn("secret-key");

		IronkinClanApiClient apiClient = new IronkinClanApiClient(config);
		httpClient = mock(OkHttpClient.class);
		itemManager = mock(ItemManager.class);
		clientThread = mock(ClientThread.class);
		call = mock(Call.class);

		// fetch() resolves item names inside clientThread.invoke(); run it synchronously so
		// tests can assert on the result immediately.
		doAnswer(invocation ->
		{
			Runnable runnable = invocation.getArgument(0);
			runnable.run();
			return null;
		}).when(clientThread).invoke(any(Runnable.class));

		when(httpClient.newCall(any(Request.class))).thenReturn(call);

		executor = mock(ScheduledExecutorService.class);
		// Run scheduled retries synchronously and immediately so tests don't need to deal with
		// real delays - the backoff duration itself isn't the concern of these tests.
		doAnswer(invocation ->
		{
			Runnable retry = invocation.getArgument(0);
			retry.run();
			return null;
		}).when(executor).schedule(any(Runnable.class), anyLong(), any(TimeUnit.class));

		manager = new TrackedItemManager(config, apiClient, httpClient, new Gson(), itemManager, clientThread, executor);

		diagnosticListener = mock(DiagnosticListener.class);
		listener = mock(TrackedItemManager.Listener.class);
		manager.setDiagnosticListener(diagnosticListener);
		manager.setListener(listener);

		nameItem(20997, "Twisted bow");
		nameItem(11840, "Dragon warhammer");
	}

	private void nameItem(int itemId, String name)
	{
		ItemComposition composition = mock(ItemComposition.class);
		when(composition.getName()).thenReturn(name);
		when(itemManager.getItemComposition(itemId)).thenReturn(composition);
	}

	private void respondWithSuccess(String json)
	{
		respondWith(200, json);
	}

	private void respondWith(int code, String body)
	{
		doAnswer(invocation ->
		{
			Callback callback = invocation.getArgument(0);
			Response response = new Response.Builder()
				.request(new Request.Builder().url("https://ironkin.example.com/events/item-list").build())
				.protocol(Protocol.HTTP_1_1)
				.code(code)
				.message(code == 200 ? "OK" : "Error")
				.body(ResponseBody.create(MediaType.get("application/json; charset=utf-8"), body))
				.build();
			callback.onResponse(call, response);
			return null;
		}).when(call).enqueue(any(Callback.class));
	}

	private void respondWithFailure(IOException exception)
	{
		doAnswer(invocation ->
		{
			Callback callback = invocation.getArgument(0);
			callback.onFailure(call, exception);
			return null;
		}).when(call).enqueue(any(Callback.class));
	}

	@Test
	public void fetch_missingServerUrl_skipsRequestAndNotifiesDiagnostic()
	{
		when(config.serverUrl()).thenReturn("");

		manager.fetch();

		verify(httpClient, never()).newCall(any(Request.class));
		verify(diagnosticListener).onDiagnosticEvent(anyString(), eq(false));
	}

	@Test
	public void fetch_missingApiKey_skipsRequestAndNotifiesDiagnostic()
	{
		when(config.apiKey()).thenReturn("");

		manager.fetch();

		verify(httpClient, never()).newCall(any(Request.class));
		verify(diagnosticListener).onDiagnosticEvent(anyString(), eq(false));
	}

	@Test
	@SuppressWarnings("unchecked")
	public void fetch_successfulResponse_populatesTrackedItemsAndNotifiesListener()
	{
		respondWithSuccess("{ \"events\": ["
			+ "{ \"eventId\": \"bounty-123\", \"items\": [20997] },"
			+ "{ \"eventId\": \"botw-123\", \"items\": [11840, 20997] }"
			+ "] }");

		manager.fetch();

		assertTrue(manager.hasTrackedItems());
		assertEquals("Twisted bow", manager.getItemName(20997));
		assertEquals("Dragon warhammer", manager.getItemName(11840));

		ArgumentCaptor<List<TrackedEventGroup>> captor = ArgumentCaptor.forClass(List.class);
		verify(listener).onTrackedItemsUpdated(captor.capture());
		assertEquals(2, captor.getValue().size());
	}

	@Test
	@SuppressWarnings("unchecked")
	public void fetch_eventWithPassword_populatesEventPasswordOnGroup()
	{
		respondWithSuccess("{ \"events\": ["
			+ "{ \"eventId\": \"bounty-123\", \"items\": [20997], \"eventPassword\": \"ironkin-password\" },"
			+ "{ \"eventId\": \"botw-123\", \"items\": [11840] }"
			+ "] }");

		manager.fetch();

		ArgumentCaptor<List<TrackedEventGroup>> captor = ArgumentCaptor.forClass(List.class);
		verify(listener).onTrackedItemsUpdated(captor.capture());

		List<TrackedEventGroup> events = captor.getValue();
		assertEquals("ironkin-password", events.get(0).eventPassword);
		assertNull(events.get(1).eventPassword);
	}

	@Test
	public void fetch_itemTrackedByMultipleEvents_getEventIdsForItemReturnsBoth()
	{
		respondWithSuccess("{ \"events\": ["
			+ "{ \"eventId\": \"bounty-123\", \"items\": [20997] },"
			+ "{ \"eventId\": \"botw-123\", \"items\": [11840, 20997] }"
			+ "] }");

		manager.fetch();

		List<String> eventIds = manager.getEventIdsForItem(20997);
		assertEquals(2, eventIds.size());
		assertTrue(eventIds.contains("bounty-123"));
		assertTrue(eventIds.contains("botw-123"));
		assertEquals(Collections.singletonList("botw-123"), manager.getEventIdsForItem(11840));
	}

	@Test
	public void fetch_itemNotTracked_getEventIdsForItemReturnsEmpty()
	{
		respondWithSuccess("{ \"events\": [ { \"eventId\": \"bounty-123\", \"items\": [20997] } ] }");

		manager.fetch();

		assertTrue(manager.getEventIdsForItem(999).isEmpty());
	}

	@Test
	public void fetch_httpError_notifiesDiagnosticAndAllowsRetry()
	{
		respondWith(500, "");

		manager.fetch();

		verify(diagnosticListener).onDiagnosticEvent(anyString(), eq(false));
		assertFalse(manager.hasTrackedItems());

		// A failed fetch should reset the in-flight flag so a subsequent fetch is allowed.
		respondWithSuccess("{ \"events\": [ { \"eventId\": \"bounty-123\", \"items\": [20997] } ] }");
		manager.fetch();

		assertTrue(manager.hasTrackedItems());
	}

	@Test
	public void fetch_emptyResponseBody_notifiesDiagnosticWithoutCrashing()
	{
		respondWithSuccess("");

		manager.fetch();

		verify(diagnosticListener).onDiagnosticEvent(anyString(), eq(false));
		assertFalse(manager.hasTrackedItems());
	}

	@Test
	public void fetch_responseWrongJsonType_notifiesDiagnosticWithoutCrashing()
	{
		// Valid JSON, but the wrong shape (array instead of object) - triggers Gson's
		// JsonSyntaxException path rather than the "empty/malformed" null-body path.
		respondWithSuccess("[1, 2, 3]");

		manager.fetch();

		verify(diagnosticListener).onDiagnosticEvent(anyString(), eq(false));
		assertFalse(manager.hasTrackedItems());
	}

	@Test
	public void fetch_emptyEventsList_treatsAsEmptyTrackedItems()
	{
		respondWithSuccess("{ \"events\": [] }");

		manager.fetch();

		assertFalse(manager.hasTrackedItems());
		verify(listener).onTrackedItemsUpdated(Collections.emptyList());
	}

	@Test
	public void fetch_networkFailure_retriesTwiceThenNotifiesDiagnostic()
	{
		respondWithFailure(new IOException("boom"));

		manager.fetch();

		// Initial attempt + 2 retries.
		verify(httpClient, times(3)).newCall(any(Request.class));
		verify(diagnosticListener).onDiagnosticEvent(anyString(), eq(false));
		assertFalse(manager.hasTrackedItems());
	}

	@Test
	public void fetch_networkFailure_retriesWithIncreasingBackoff()
	{
		respondWithFailure(new IOException("boom"));

		manager.fetch();

		ArgumentCaptor<Long> delayCaptor = ArgumentCaptor.forClass(Long.class);
		verify(executor, times(2)).schedule(any(Runnable.class), delayCaptor.capture(), eq(TimeUnit.MILLISECONDS));
		assertEquals(2000L, (long) delayCaptor.getAllValues().get(0));
		assertEquals(4000L, (long) delayCaptor.getAllValues().get(1));
	}

	@Test
	public void fetch_networkFailureThenSuccessOnRetry_populatesTrackedItems()
	{
		// Fail on the first attempt, then succeed on the retry.
		doAnswer(invocation ->
		{
			Callback callback = invocation.getArgument(0);
			callback.onFailure(call, new IOException("boom"));
			return null;
		}).doAnswer(invocation ->
		{
			Callback callback = invocation.getArgument(0);
			Response response = new Response.Builder()
				.request(new Request.Builder().url("https://ironkin.example.com/events/item-list").build())
				.protocol(Protocol.HTTP_1_1)
				.code(200)
				.message("OK")
				.body(ResponseBody.create(MediaType.get("application/json; charset=utf-8"),
					"{ \"events\": [ { \"eventId\": \"bounty-123\", \"items\": [20997] } ] }"))
				.build();
			callback.onResponse(call, response);
			return null;
		}).when(call).enqueue(any(Callback.class));

		manager.fetch();

		verify(httpClient, times(2)).newCall(any(Request.class));
		assertTrue(manager.hasTrackedItems());
		verify(diagnosticListener, never()).onDiagnosticEvent(anyString(), eq(false));
	}

	@Test
	public void fetch_whileRequestInFlight_doesNotIssueSecondCall()
	{
		// Deliberately leave call.enqueue(...) unstubbed (a no-op) to simulate a request that
		// hasn't completed yet.
		manager.fetch();
		manager.fetch();

		verify(httpClient, times(1)).newCall(any(Request.class));
	}

	@Test
	public void reset_clearsTrackedState()
	{
		respondWithSuccess("{ \"events\": [ { \"eventId\": \"bounty-123\", \"items\": [20997] } ] }");
		manager.fetch();
		assertTrue(manager.hasTrackedItems());

		manager.reset();

		assertFalse(manager.hasTrackedItems());
		assertTrue(manager.getEventIdsForItem(20997).isEmpty());
	}
}

package com.ironkinclan.manager;

import java.util.Arrays;
import java.util.Collections;
import net.runelite.api.Client;
import net.runelite.api.IndexedObjectSet;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.clan.ClanChannel;
import net.runelite.api.clan.ClanChannelMember;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class ClanMemberManagerTest
{
	private Client client;
	private WorldView worldView;
	private ClanChannel clanChannel;
	private ClanMemberManager manager;

	@Before
	public void setUp()
	{
		client = mock(Client.class);
		worldView = mock(WorldView.class);
		clanChannel = mock(ClanChannel.class);
		when(client.getTopLevelWorldView()).thenReturn(worldView);
		when(client.getClanChannel()).thenReturn(clanChannel);

		manager = new ClanMemberManager(client);
	}

	private static Player player(String name)
	{
		Player player = mock(Player.class);
		when(player.getName()).thenReturn(name);
		return player;
	}

	@SuppressWarnings({"unchecked", "rawtypes"})
	private void mockNearbyPlayers(Player... players)
	{
		IndexedObjectSet playerSet = mock(IndexedObjectSet.class);
		when(playerSet.iterator()).thenReturn(Arrays.asList(players).iterator());
		when(worldView.players()).thenReturn(playerSet);
	}

	@Test
	public void getNearbyGroupComposition_noClanChannel_noClanPlayersAndEmptyMembers()
	{
		Player someone = player("Someone");
		when(client.getClanChannel()).thenReturn(null);
		mockNearbyPlayers(someone);

		GroupComposition composition = manager.getNearbyGroupComposition();

		assertEquals(1, composition.totalPlayers);
		assertEquals(0, composition.clanPlayers);
		assertTrue(composition.clanMembers.isEmpty());
	}

	@Test
	public void getNearbyGroupComposition_countsClanPlayersAndExcludesLocalPlayerFromMembersList()
	{
		Player localPlayer = player("LocalPlayer");
		Player clanmate = player("Clanmate");
		Player stranger = player("Stranger");

		when(client.getLocalPlayer()).thenReturn(localPlayer);
		mockNearbyPlayers(localPlayer, clanmate, stranger);

		when(clanChannel.findMember(eq("LocalPlayer"))).thenReturn(mock(ClanChannelMember.class));
		when(clanChannel.findMember(eq("Clanmate"))).thenReturn(mock(ClanChannelMember.class));
		when(clanChannel.findMember(eq("Stranger"))).thenReturn(null);

		GroupComposition composition = manager.getNearbyGroupComposition();

		assertEquals(3, composition.totalPlayers);
		assertEquals(2, composition.clanPlayers);
		assertEquals(Collections.singletonList("Clanmate"), composition.clanMembers);
