package com.ironkinclan.api;

import com.ironkinclan.config.IronkinClanConfig;
import javax.inject.Inject;
import okhttp3.MediaType;
import okhttp3.Request;

/**
 * Builds authenticated requests against the Ironkin server's events API, shared by
 * {@link com.ironkinclan.manager.TrackedItemManager} and
 * {@link com.ironkinclan.manager.DropSubmissionManager}.
 */
public class IronkinClanApiClient
{
	public static final String API_KEY_HEADER = "x-api-key";
	public static final MediaType JSON = MediaType.get("application/json; charset=utf-8");

	private final IronkinClanConfig config;

	@Inject
	public IronkinClanApiClient(IronkinClanConfig config)
	{
		this.config = config;
	}

	public Request.Builder newItemListRequest()
	{
		return authenticatedRequest(baseUrl() + "/events/item-list");
	}

	public Request.Builder newEmberBalanceRequest()
	{
		return authenticatedRequest(baseUrl() + "/api/embers/me");
	}

	public Request.Builder newSubmissionRequest(String eventId)
	{
		return authenticatedRequest(baseUrl() + "/events/" + eventId + "/submissions");
	}

	private Request.Builder authenticatedRequest(String url)
	{
		return new Request.Builder()
			.url(url)
			.header(API_KEY_HEADER, config.apiKey());
	}

	private String baseUrl()
	{
		String url = config.serverUrl();
		return url.endsWith("/") ? url.substring(0, url.length() - 1) : url;
	}
}

package com.ironkinclan.api;

import java.io.IOException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/**
 * Enqueues an OkHttp request, retrying with an exponential backoff on network-level
 * failures (timeouts, connection resets, DNS failures, etc. - anything that reaches
 * {@link Callback#onFailure}). HTTP error responses (4xx/5xx) are not retried here: the
 * server received and processed the request, so an immediate retry is unlikely to help,
 * and callers already treat those as terminal failures.
 */
@Slf4j
public final class RetryingCall
{
	private static final int MAX_RETRIES = 2;
	private static final long INITIAL_BACKOFF_MS = 2000;

	private RetryingCall()
	{
	}

	public static void enqueue(OkHttpClient httpClient, ScheduledExecutorService executor, Request request, Callback callback)
	{
		attempt(httpClient, executor, request, callback, 0);
	}

	private static void attempt(OkHttpClient httpClient, ScheduledExecutorService executor, Request request, Callback callback, int retryCount)
	{
		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				if (retryCount >= MAX_RETRIES)
				{
					callback.onFailure(call, e);
					return;
				}

				long delayMs = INITIAL_BACKOFF_MS << retryCount;
				log.debug("Request to {} failed ({}); retrying in {}ms (attempt {}/{})",
					request.url(), e.getMessage(), delayMs, retryCount + 1, MAX_RETRIES);
				executor.schedule(() -> attempt(httpClient, executor, request, callback, retryCount + 1),
					delayMs, TimeUnit.MILLISECONDS);
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				callback.onResponse(call, response);
			}
		});
	}
}

package com.ironkinclan;

import com.google.inject.Provides;
import com.ironkinclan.config.IronkinClanConfig;
import com.ironkinclan.manager.ClanMemberManager;
import com.ironkinclan.manager.DropSubmissionManager;
import com.ironkinclan.manager.EmberManager;
import com.ironkinclan.manager.GroupComposition;
import com.ironkinclan.manager.TrackedItemManager;
import com.ironkinclan.model.TrackedEventGroup;
import com.ironkinclan.ui.EventPasswordOverlay;
import com.ironkinclan.ui.IronkinClanPanel;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.events.ConfigChanged;
