import net.runelite.http.api.loottracker.LootRecordType;

@Slf4j
@PluginDescriptor(
	name = "Ironkin Clan"
)
public class IronkinClanPlugin extends Plugin
{
	// Renamed from "showUploadLog" when the panel log was expanded to also show diagnostic
	// warnings (e.g. failed item list fetches), not just drop upload results.
	private static final String OLD_SHOW_UPLOAD_LOG_KEY = "showUploadLog";

	// Server-side event ID for the group boss PvM entry-fee event. Drops reported to this event
	// also credit nearby clan members, since group bosses are commonly killed together.
	private static final String GROUP_BOSS_EVENT_ID = "pvm-entry";

	@Inject
	private Client client;

	@Inject
	private IronkinClanConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private EventPasswordOverlay eventPasswordOverlay;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ClientThread clientThread;

	@Inject
	private TrackedItemManager trackedItemManager;

	@Inject
	private DropSubmissionManager dropSubmissionManager;

	@Inject
	private ClanMemberManager clanMemberManager;

	@Inject
	private EmberManager emberManager;

	private IronkinClanPanel panel;
	private NavigationButton navButton;
	private List<TrackedEventGroup> lastTrackedEvents = Collections.emptyList();

	@Override
	protected void startUp()
	{
		migrateShowUploadLogKey();
		removeObsoleteBingoIdKey();

		panel = new IronkinClanPanel(itemManager);

		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Ironkin Clan")
			.icon(icon)
			.priority(5)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		panel.setLogVisible(config.showDebugLog());
		panel.setOnActivate(this::onPanelActivated);

		overlayManager.add(eventPasswordOverlay);

		trackedItemManager.setListener(this::onTrackedItemsUpdated);
		trackedItemManager.setDiagnosticListener(this::logDiagnostic);
		dropSubmissionManager.setListener(this::logUploadEvent);

		if (config.enableDropTracking())
		{
			trackedItemManager.fetch();
		}

		emberManager.setListener(this::onEmberBalanceUpdated);
		emberManager.setDiagnosticListener(this::logDiagnostic);
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			emberManager.start();
		}
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(navButton);
		overlayManager.remove(eventPasswordOverlay);
		trackedItemManager.setListener(null);
		trackedItemManager.setDiagnosticListener(null);
		trackedItemManager.reset();
		dropSubmissionManager.setListener(null);
		lastTrackedEvents = Collections.emptyList();

		emberManager.stop();
		emberManager.setListener(null);
		emberManager.setDiagnosticListener(null);
		emberManager.reset();
	}

	private void onPanelActivated()
	{
		trackedItemManager.refresh();
		emberManager.fetch();
	}

	private void onTrackedItemsUpdated(List<TrackedEventGroup> events)
	{
		lastTrackedEvents = events;
		panel.setTrackedItems(events);
		updateEventPasswordOverlay();
	}

	private void updateEventPasswordOverlay()
	{
		if (!config.showEventPasswords())
		{
			eventPasswordOverlay.setPasswordEvents(Collections.emptyList());
			return;
		}

		List<TrackedEventGroup> passwordEvents = new ArrayList<>();
		for (TrackedEventGroup event : lastTrackedEvents)
		{
			if (event.eventPassword != null && !event.eventPassword.isEmpty())
			{
				passwordEvents.add(event);
			}
		}

		eventPasswordOverlay.setPasswordEvents(passwordEvents);
	}

	private void migrateShowUploadLogKey()
	{
		String oldValue = configManager.getConfiguration(IronkinClanConfig.CONFIG_GROUP, OLD_SHOW_UPLOAD_LOG_KEY);
		if (oldValue != null)
		{
			configManager.setConfiguration(IronkinClanConfig.CONFIG_GROUP, "showDebugLog", oldValue);
			configManager.unsetConfiguration(IronkinClanConfig.CONFIG_GROUP, OLD_SHOW_UPLOAD_LOG_KEY);
		}
	}

	// The plugin no longer needs a user-configured event/bingo ID: the /events API now returns
	// every active event for the given API key, so this setting is obsolete.
	private void removeObsoleteBingoIdKey()
	{
		configManager.unsetConfiguration(IronkinClanConfig.CONFIG_GROUP, "bingoId");
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!IronkinClanConfig.CONFIG_GROUP.equals(event.getGroup()))
		{
			return;
		}

		switch (event.getKey())
		{
			case "serverUrl":
			case "apiKey":
				trackedItemManager.reset();
				onTrackedItemsUpdated(Collections.emptyList());
				if (config.enableDropTracking())
				{
					trackedItemManager.fetch();
				}
				emberManager.reset();
				emberManager.fetch();
				break;
			case "enableDropTracking":
				if (config.enableDropTracking())
				{
					trackedItemManager.fetch();
				}
				break;
			case "showDebugLog":
				panel.setLogVisible(config.showDebugLog());
				break;
			case "showEventPasswords":
				updateEventPasswordOverlay();
				break;
			default:
				break;
		}
	}

	// The startUp() fetch above only fires once and, if it fails (e.g. the server is briefly
	// unreachable while the client is still booting), nothing retries it unless the user happens
	// to open the panel. Retrying on every login is a cheap, panel-independent backstop:
	// fetch() is a no-op once the list has already loaded, so this only does real work when the
	// initial attempt never succeeded.
	//
	// Ember polling is also started/stopped here: it's only meaningful while actively logged in,
	// so it starts on login and stops once the client returns to the login screen rather than
	// running unattended in the background.
	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();

		if (state == GameState.LOGGED_IN)
		{
			if (config.enableDropTracking())
			{
				trackedItemManager.fetch();
			}
			emberManager.start();
		}
		else if (state == GameState.LOGIN_SCREEN)
		{
			emberManager.stop();
		}
	}

	// Uses the built-in Loot Tracker plugin's LootReceived broadcast rather than NpcLootReceived,
	// since Loot Tracker already funnels NPC kills, clue scroll rewards, raid/Barrows chests, and
	// most minigame rewards through one addLoot() call that posts this event. This only fires if
	// the user has the "Loot Tracker" plugin enabled (on by default, but can be disabled).
	//
	// PLAYER-type loot (PvP kills) is deliberately excluded and shouldn't be added: it would
	// report another player's gear to a third-party server, which is explicitly called out as a
	// rejected plugin behavior ("crowdsourcing data about other players... gear...").
	@Subscribe
	public void onLootReceived(LootReceived event)
	{
		if (!config.enableDropTracking())
		{
			return;
		}

		if (event.getType() == LootRecordType.PLAYER)
		{
			logDiagnostic("Ignoring PLAYER-type loot from " + event.getName() + " - PvP loot is intentionally not tracked", false);
			return;
		}

		if (!trackedItemManager.hasTrackedItems())
		{
			logDiagnostic("Ignoring loot from " + event.getName() + ": no tracked items loaded yet", false);
			return;
		}

		if (client.getLocalPlayer() == null)
		{
			logDiagnostic("Ignoring loot from " + event.getName() + ": local player is not available", false);
			return;
		}

		String username = client.getLocalPlayer().getName();
		log.debug("Processing loot event from {} ({}): {} item stack(s)", event.getName(), event.getType(), event.getItems().size());

		// The nearby group is only relevant to the group boss event, so this is looked up at most
		// once per loot event rather than unconditionally on every drop.
		GroupComposition groupComposition = null;

		for (ItemStack item : event.getItems())
		{
			String itemName = trackedItemManager.getItemName(item.getId());
			if (itemName == null)
			{
				continue;
			}

			List<String> eventIds = trackedItemManager.getEventIdsForItem(item.getId());
			if (eventIds.isEmpty())
			{
				// Shouldn't happen - getItemName() only resolves names for items that came from
				// an event's list in the first place - but log it if the two ever disagree.
				logDiagnostic("Tracked item " + itemName + " (" + item.getId() + ") matched no events; skipping", false);
				continue;
			}

			log.debug("Matched tracked item {} ({}) x{} - reporting to event(s) {}", item.getId(), itemName, item.getQuantity(), eventIds);

			for (String eventId : eventIds)
			{
				List<String> participants = Collections.emptyList();
				if (GROUP_BOSS_EVENT_ID.equals(eventId))
				{
					if (groupComposition == null)
					{
						groupComposition = clanMemberManager.getNearbyGroupComposition();
					}

					if (!groupComposition.isClanMajority())
					{
						logDiagnostic("Skipping " + itemName + " for " + eventId + ": clan was not a majority of the group ("
							+ groupComposition.clanPlayers + "/" + groupComposition.totalPlayers + ")", false);
						continue;
					}

					participants = groupComposition.clanMembers;
				}

				dropSubmissionManager.reportDrop(eventId, username, item.getId(), itemName, participants);
			}
		}
	}

	// Drop upload results are actionable per-event feedback, so they're echoed to game chat in
	// addition to the panel log. The panel always records the entry regardless of showDebugLog -
	// that setting only controls whether the log section is visible (see setLogVisible), so
	// toggling it on later reveals everything that happened while it was hidden instead of only
	// entries logged from that point forward.
	private void logUploadEvent(String text, boolean success)
	{
		panel.addLogEntry(text, success);

		clientThread.invoke(() -> client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "[Ironkin Clan] " + text, null));
	}

	// Diagnostic warnings (e.g. a failed tracked item list fetch) are background/setup issues,
	// not per-event feedback, so they only go to the panel log rather than spamming game chat.
	private void logDiagnostic(String text, boolean success)
	{
		panel.addLogEntry(text, success);
	}

	// Only announce increases in chat: embers are earned, not spent through this client, so a
	// decrease would just be a correction on the server side rather than something to celebrate.
	private void onEmberBalanceUpdated(int balance, Integer delta)
	{
		panel.setEmberBalance(balance);

		if (delta != null && delta > 0)
		{
			String message = "[Ironkin]: You have been awarded " + delta + " embers. Your total ember balance is now: " + balance + " embers.";
			clientThread.invoke(() -> client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null));
		}
	}

	@Provides
	IronkinClanConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(IronkinClanConfig.class);
	}
}

package com.ironkinclan.manager;

import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.clan.ClanChannel;

/**
 * Reports on the nearby player group at a kill: who else is there, and how many of them are
 * members of the local player's in-game Clan, for features (like group boss submissions) that
 * need to know who was present and whether the clan made up the group.
 */
public class ClanMemberManager
{
	private final Client client;

	@Inject
	public ClanMemberManager(Client client)
	{
		this.client = client;
	}

	// Reads the top-level WorldView's players and the clan channel, so must be called on the
	// client thread.
	public GroupComposition getNearbyGroupComposition()
	{
		ClanChannel clanChannel = client.getClanChannel();
		Player localPlayer = client.getLocalPlayer();
		String localName = localPlayer == null ? null : localPlayer.getName();

		int totalPlayers = 0;
		int clanPlayers = 0;
		List<String> clanMembers = new ArrayList<>();

		for (Player player : client.getTopLevelWorldView().players())
		{
			String name = player.getName();
			if (name == null)
			{
				continue;
			}

			totalPlayers++;

			if (clanChannel == null || clanChannel.findMember(name) == null)
			{
				continue;
			}

			clanPlayers++;
			if (!name.equals(localName))
			{
				clanMembers.add(name);
			}
		}

		return new GroupComposition(totalPlayers, clanPlayers, clanMembers);
	}
}

package com.ironkinclan.manager;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.ironkinclan.api.IronkinClanApiClient;
import com.ironkinclan.api.RetryingCall;
import com.ironkinclan.config.IronkinClanConfig;
import com.ironkinclan.model.TrackedEventGroup;
import com.ironkinclan.model.TrackedItem;
import java.io.IOException;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.atomic.AtomicBoolean;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/**
 * Fetches and caches the tracked item lists for every active event returned by the server,
 * resolving item names on the client thread via {@link ItemManager}.
 */
@Slf4j
public class TrackedItemManager
{
	public interface Listener
	{
		void onTrackedItemsUpdated(List<TrackedEventGroup> events);
	}

	private final IronkinClanConfig config;
	private final IronkinClanApiClient apiClient;
	private final OkHttpClient httpClient;
	private final Gson gson;
	private final ItemManager itemManager;
	private final ClientThread clientThread;
	private final ScheduledExecutorService executor;

	@Inject
	public TrackedItemManager(IronkinClanConfig config, IronkinClanApiClient apiClient, OkHttpClient httpClient,
		Gson gson, ItemManager itemManager, ClientThread clientThread, ScheduledExecutorService executor)
	{
		this.config = config;
		this.apiClient = apiClient;
		this.httpClient = httpClient;
		this.gson = gson;
		this.itemManager = itemManager;
		this.clientThread = clientThread;
		this.executor = executor;
	}

	// eventId -> item IDs tracked by that event
	private final Map<String, Set<Integer>> eventItemIds = new ConcurrentHashMap<>();
	// itemId -> resolved name, union across all events
	private final Map<Integer, String> itemNames = new ConcurrentHashMap<>();
	private final AtomicBoolean itemListRequested = new AtomicBoolean();

	private Listener listener;
	private DiagnosticListener diagnosticListener;

	public void setListener(Listener listener)
	{
		this.listener = listener;
	}

	public void setDiagnosticListener(DiagnosticListener diagnosticListener)
	{
		this.diagnosticListener = diagnosticListener;
	}

	public boolean hasTrackedItems()
	{
		return !itemNames.isEmpty();
	}

	public String getItemName(int itemId)
	{
		return itemNames.get(itemId);
	}

	public List<String> getEventIdsForItem(int itemId)
	{
		List<String> matches = new ArrayList<>();
		for (Map.Entry<String, Set<Integer>> entry : eventItemIds.entrySet())
		{
			if (entry.getValue().contains(itemId))
			{
				matches.add(entry.getKey());
			}
		}
		return matches;
	}

	public void reset()
	{
		eventItemIds.clear();
		itemNames.clear();
		itemListRequested.set(false);
	}

	public void refresh()
	{
		if (!config.enableDropTracking())
		{
			return;
		}

		itemListRequested.set(false);
		fetch();
	}

	public void fetch()
	{
		if (config.serverUrl().isEmpty())
		{
			warn("Ironkin Clan server URL is not configured; skipping tracked item list fetch");
			return;
		}

		if (config.apiKey().isEmpty())
		{
			warn("Ironkin Clan API key is not configured; skipping tracked item list fetch");
			return;
		}

		if (!itemListRequested.compareAndSet(false, true))
		{
			return;
		}

		Request request = apiClient.newItemListRequest().build();

		RetryingCall.enqueue(httpClient, executor, request, new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				itemListRequested.set(false);
				warn("Failed to fetch Ironkin tracked item list: " + e.getMessage(), e);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				ItemListResponse body;
				try (Response r = response)
				{
					if (!r.isSuccessful() || r.body() == null)
					{
						itemListRequested.set(false);
						warn("Failed to fetch Ironkin tracked item list: HTTP " + r.code());
						return;
					}

					body = gson.fromJson(r.body().charStream(), ItemListResponse.class);
					if (body == null || body.events == null)
					{
						itemListRequested.set(false);
						warn("Ironkin tracked item list response was empty or malformed");
						return;
					}
				}
				catch (JsonSyntaxException e)
				{
					itemListRequested.set(false);
					warn("Failed to parse Ironkin tracked item list: " + e.getMessage(), e);
					return;
				}

				// The API only sends item IDs; resolve the canonical name from the client's own
				// item cache. ItemManager must be called on the client thread.
				clientThread.invoke(() ->
				{
					eventItemIds.clear();
					itemNames.clear();

					List<TrackedEventGroup> resolved = new ArrayList<>(body.events.size());
					for (EventEntry eventEntry : body.events)
					{
						List<TrackedItem> groupItems = new ArrayList<>(eventEntry.items.size());
						Set<Integer> ids = new HashSet<>();
						for (int itemId : eventEntry.items)
						{
							String name = itemManager.getItemComposition(itemId).getName();
							itemNames.put(itemId, name);
							ids.add(itemId);
							groupItems.add(new TrackedItem(itemId, name));
						}
						eventItemIds.put(eventEntry.eventId, ids);
						resolved.add(new TrackedEventGroup(eventEntry.eventId, groupItems, eventEntry.eventPassword));
					}

					if (listener != null)
					{
						listener.onTrackedItemsUpdated(resolved);
					}

					log.debug("Loaded {} tracked events with {} unique items", body.events.size(), itemNames.size());
				});
			}
		});
	}

	private void warn(String message)
	{
		log.warn(message);
		if (diagnosticListener != null)
		{
			diagnosticListener.onDiagnosticEvent(message, false);
		}
	}

	private void warn(String message, Throwable t)
	{
		log.warn(message, t);
		if (diagnosticListener != null)
		{
			diagnosticListener.onDiagnosticEvent(message, false);
		}
	}

	private static class ItemListResponse
	{
		List<EventEntry> events;
	}

	private static class EventEntry
	{
		String eventId;
		List<Integer> items;
		String eventPassword;
	}
}

package com.ironkinclan.manager;

import com.google.gson.Gson;
import com.google.gson.annotations.SerializedName;
import com.ironkinclan.api.IronkinClanApiClient;
import com.ironkinclan.api.RetryingCall;
import java.awt.Image;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.util.Base64;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.DrawManager;
import net.runelite.client.util.ImageUtil;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * Captures a screenshot of a tracked item drop and uploads it to the Ironkin server.
 */
@Slf4j
public class DropSubmissionManager
{
	private final IronkinClanApiClient apiClient;
	private final OkHttpClient httpClient;
	private final Gson gson;
	private final DrawManager drawManager;
	private final ScheduledExecutorService executor;

	@Inject
	public DropSubmissionManager(IronkinClanApiClient apiClient, OkHttpClient httpClient, Gson gson,
		DrawManager drawManager, ScheduledExecutorService executor)
	{
		this.apiClient = apiClient;
		this.httpClient = httpClient;
		this.gson = gson;
		this.drawManager = drawManager;
		this.executor = executor;
	}

	private DiagnosticListener listener;

	public void setListener(DiagnosticListener listener)
	{
		this.listener = listener;
	}

	public void reportDrop(String eventId, String username, int itemId, String itemName)
	{
		reportDrop(eventId, username, itemId, itemName, Collections.emptyList());
	}

	// participants is the set of other nearby clan members to credit alongside username - only
	// populated for group boss kills (see GroupBossRegistry), empty otherwise.
	public void reportDrop(String eventId, String username, int itemId, String itemName, List<String> participants)
	{
		long timestamp = System.currentTimeMillis();
		drawManager.requestNextFrameListener(image -> executor.execute(() -> uploadDrop(eventId, username, itemId, itemName, timestamp, participants, image)));
	}

	// Package-private (rather than private) so unit tests can exercise the encode/upload logic
	// directly without needing to drive the DrawManager frame-capture pipeline.
	void uploadDrop(String eventId, String username, int itemId, String itemName, long timestamp, List<String> participants, Image image)
	{
		String imageData;
		try
		{
			BufferedImage screenshot = ImageUtil.bufferedImageFromImage(image);
			ByteArrayOutputStream baos = new ByteArrayOutputStream();
			ImageIO.write(screenshot, "png", baos);
			imageData = Base64.getEncoder().encodeToString(baos.toByteArray());
		}
		catch (IOException e)
		{
			log.warn("Failed to encode Ironkin drop screenshot for item {}", itemId, e);
			notifyListener("Failed to capture screenshot for " + itemName, false);
			return;
		}

		log.debug("Encoded {} drop screenshot for {}: {} base64 chars", itemName, username, imageData.length());
		notifyListener("Captured screenshot for " + itemName + " drop", true);

		DropReport report = new DropReport(username, itemId, timestamp, imageData, participants);
		RequestBody body = RequestBody.create(IronkinClanApiClient.JSON, gson.toJson(report));

		Request request = apiClient.newSubmissionRequest(eventId)
			.post(body)
			.build();

		RetryingCall.enqueue(httpClient, executor, request, new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.warn("Failed to upload Ironkin drop report for item {} to event {}", itemId, eventId, e);
				notifyListener("Failed to send " + itemName + " drop to " + eventId + ": " + e.getMessage(), false);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response r = response)
				{
					if (!r.isSuccessful())
					{
						log.warn("Ironkin drop report upload failed for item {} to event {}: HTTP {}", itemId, eventId, r.code());
						notifyListener("Failed to send " + itemName + " drop to " + eventId + " (HTTP " + r.code() + ")", false);
					}
					else
					{
						notifyListener("Sent " + itemName + " drop for " + username + " to " + eventId, true);
					}
				}
			}
		});
	}

	private void notifyListener(String text, boolean success)
	{
		if (listener != null)
		{
			listener.onDiagnosticEvent(text, success);
		}
	}

	private static class DropReport
	{
		@SerializedName("username")
		final String username;
		@SerializedName("itemid")
		final int itemId;
		@SerializedName("timestamp")
		final long timestamp;
		@SerializedName("imageData")
		final String imageData;
		@SerializedName("participants")
		final List<String> participants;

		DropReport(String username, int itemId, long timestamp, String imageData, List<String> participants)
		{
			this.username = username;
			this.itemId = itemId;
			this.timestamp = timestamp;
			this.imageData = imageData;
			this.participants = participants;
		}
	}
}

package com.ironkinclan.manager;

import java.util.List;

/**
 * Snapshot of the nearby player group at the moment of a drop: how many players are present in
 * total, how many of them are in the local player's clan, and their names (excluding the local
 * player, who is implied to be one of clanPlayers if the local player is themselves in the clan).
 */
public class GroupComposition
{
	public final int totalPlayers;
	public final int clanPlayers;
	public final List<String> clanMembers;

	public GroupComposition(int totalPlayers, int clanPlayers, List<String> clanMembers)
	{
		this.totalPlayers = totalPlayers;
		this.clanPlayers = clanPlayers;
		this.clanMembers = clanMembers;
	}

	// A strict majority (more than half) of the group must be in the clan. Solo kills never
	// qualify, even though a lone clan member would otherwise be a 100% majority of 1.
	public boolean isClanMajority()
	{
		return totalPlayers > 1 && clanPlayers * 2 > totalPlayers;
	}
}

package com.ironkinclan.manager;

public interface DiagnosticListener
{
	void onDiagnosticEvent(String text, boolean success);
}

package com.ironkinclan.manager;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.ironkinclan.api.IronkinClanApiClient;
import com.ironkinclan.config.IronkinClanConfig;
import java.io.IOException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/**
 * Polls the member's ember balance on a fixed interval. Unlike {@link TrackedItemManager}, this
 * intentionally does not use {@link com.ironkinclan.api.RetryingCall}: a failed poll is
 * superseded by the next scheduled poll a few minutes later anyway, so retrying just adds delay
 * without adding value.
 */
@Slf4j
public class EmberManager
{
	private static final long POLL_INTERVAL_MINUTES = 5;

	public interface Listener
	{
		// delta is the change since the last successful poll, or null if this is the first poll
		// or the balance hasn't changed.
		void onEmberBalanceUpdated(int balance, Integer delta);
	}

	private final IronkinClanConfig config;
	private final IronkinClanApiClient apiClient;
	private final OkHttpClient httpClient;
	private final Gson gson;
	private final ScheduledExecutorService executor;

	private volatile Integer lastBalance;
	private ScheduledFuture<?> pollTask;

	private Listener listener;
	private DiagnosticListener diagnosticListener;

	@Inject
	public EmberManager(IronkinClanConfig config, IronkinClanApiClient apiClient, OkHttpClient httpClient,
		Gson gson, ScheduledExecutorService executor)
	{
		this.config = config;
		this.apiClient = apiClient;
		this.httpClient = httpClient;
		this.gson = gson;
		this.executor = executor;
	}

	public void setListener(Listener listener)
	{
		this.listener = listener;
	}

	public void setDiagnosticListener(DiagnosticListener diagnosticListener)
	{
		this.diagnosticListener = diagnosticListener;
	}

	public void start()
	{
		stop();
		fetch();
		pollTask = executor.scheduleAtFixedRate(this::fetch, POLL_INTERVAL_MINUTES, POLL_INTERVAL_MINUTES, TimeUnit.MINUTES);
	}

	public void stop()
	{
		if (pollTask != null)
		{
			pollTask.cancel(false);
			pollTask = null;
		}
	}

	public void reset()
	{
		lastBalance = null;
	}

	public void fetch()
	{
		if (config.serverUrl().isEmpty() || config.apiKey().isEmpty())
		{
			return;
		}

		Request request = apiClient.newEmberBalanceRequest().build();

		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				warn("Failed to fetch Ironkin ember balance: " + e.getMessage(), e);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				EmberBalanceResponse body;
				try (Response r = response)
				{
					if (!r.isSuccessful() || r.body() == null)
					{
						warn("Failed to fetch Ironkin ember balance: HTTP " + r.code());
						return;
					}

					body = gson.fromJson(r.body().charStream(), EmberBalanceResponse.class);
					if (body == null)
					{
						warn("Ironkin ember balance response was empty or malformed");
						return;
					}
				}
				catch (JsonSyntaxException e)
				{
					warn("Failed to parse Ironkin ember balance: " + e.getMessage(), e);
					return;
				}

				Integer previousBalance = lastBalance;
				lastBalance = body.balance;

				Integer delta = (previousBalance != null && previousBalance != body.balance)
					? body.balance - previousBalance
					: null;

				log.debug("Ember balance updated: {} (previous: {})", body.balance, previousBalance);

				if (listener != null)
				{
					listener.onEmberBalanceUpdated(body.balance, delta);
				}
			}
		});
	}

	private void warn(String message)
	{
		log.warn(message);
		if (diagnosticListener != null)
		{
			diagnosticListener.onDiagnosticEvent(message, false);
		}
	}

	private void warn(String message, Throwable t)
	{
		log.warn(message, t);
		if (diagnosticListener != null)
		{
			diagnosticListener.onDiagnosticEvent(message, false);
		}
	}

	private static class EmberBalanceResponse
	{
		int balance;
	}
}
